CRITERIA={'positive_gain':'Paired patient-bootstrap95% lower limit of72h AUPRC difference >0','shadow':'At least6/10 signals have a positive lower limit of equal-patient mean MAE improvement vs generic TRAIN median in oracle-stable TEST windows','calibration':'Full Twin each horizon slope0.8–1.2, absolute intercept<=0.25 and Brier below the constant-prevalence Brier','challenge':'Full Twin vs population challenge AUPRC improvement has positive95% lower limit','ehr':'Full Twin vs no-EHR and original vs patient-EHR permutation both have positive72h AUPRC improvement lower limits','robustness':'Full Twin AUPRC in each of high-noise and high-missingness >=70% of matched normal-noise AUPRC, and consumer AUPRC>=80% of full Twin on main TEST','go':'All six scientific dimensions plus robustness pass; otherwise PARTIAL GO only if the full Twin72h AP lower limit exceeds prevalence; otherwise NO-GO','scope':'Engineering research gates fixed beforeTEST, not clinical acceptance criteria. Multiple component comparisons exploratory, no multiplicity correction; effect sizes/CIs retained.'}


def register(config):
    private_json(Path(config['output'])/'decision_registration.json',{'criteria':CRITERIA,'test_used':False,**EVIDENCE})

def fmt(x):return 'undefined' if x is None else f'{x:.4f}' if isinstance(x,(float,int)) else str(x)
def ci(record):return 'undefined' if not record.get('interval95') else '['+', '.join(fmt(v) for v in record['interval95'])+']'
def table(headers,rows):return '| '+' | '.join(headers)+' |\n| '+' | '.join('---' for _ in headers)+' |\n'+''.join('| '+' | '.join(str(x).replace('|','/') for x in row)+' |\n' for row in rows)
def positive(record):return bool(record.get('interval95') and record['interval95'][0]>0)
def effect_statement(record):
    interval=record.get('interval95')
    return 'Supported gain' if interval and interval[0]>0 else 'Supported loss' if interval and interval[1]<0 else 'Inconclusive'

def decide(result):
    pairs=result['paired_auprc72_differences'];cal=result['models']['full_twin']['horizons'];signals=result['shadow']['test_oracle_stable48']['signals'];shadow_count=sum(positive(r['paired_patient_mae_gain']) for r in signals.values());normal=result['stress']['variants']['normal_noise']['models']['full_twin']['metrics']['72']['metrics']['auprc'];full=result['models']['full_twin']['horizons']['72']['metrics']['auprc'];consumer=result['models']['consumer_twin']['horizons']['72']['metrics']['auprc']
    checks={'personalization':positive(pairs['personalized_fusion_vs_population_fusion']),'shadow':shadow_count>=6,'tdi_increment':positive(pairs['full_twin_vs_full_no_tdi']),'challenge':positive(result['challenge']['comparisons'].get('full_twin_vs_population_fusion',{})),'ehr':positive(pairs['full_twin_vs_full_no_ehr']) and positive(result['ehr_control']['paired_auprc72_original_minus_permuted']),'calibration':all(r['calibration']['slope'] is not None and .8<=r['calibration']['slope']<=1.2 and r['calibration']['intercept'] is not None and abs(r['calibration']['intercept'])<=.25 and r['metrics']['brier']<r['metrics']['prevalence']*(1-r['metrics']['prevalence']) for r in cal.values()),'sensor_robustness':normal is not None and all(result['stress']['variants'][v]['models']['full_twin']['metrics']['72']['metrics']['auprc']>=.7*normal for v in ['high_sensor_noise','high_missingness']) and consumer>=.8*full}
    lower=result['models']['full_twin']['patient_bootstrap95']['72']['auprc']['interval95'];prevalence=result['models']['full_twin']['horizons']['72']['metrics']['prevalence'];predictive=bool(lower and lower[0]>prevalence);decision='GO' if all(checks.values()) else 'PARTIAL GO' if predictive else 'NO-GO'
    recommendation='Proceed to Phase6.5 as a synthetic research prototype, retaining these frozen baselines and requiring new development-only experiments before any new test.' if decision=='GO' else 'Restrict Phase6.5 to uncertainty/sensor engineering research and investigate failed scientific gates on development data. Do not claim an advanced validated Digital Twin or build self-evolving/treatment layers.' if decision=='PARTIAL GO' else 'Do not proceed to the advanced innovation layer; revise the research design on development data and validate in a new independent cohort.'
    return {'decision':decision,'scientific_gates':checks,'shadow_signals_with_supported_gain':shadow_count,'full_twin_predictive_vs_prevalence':predictive,'criteria':CRITERIA,'phase6_5_recommendation':recommendation,**EVIDENCE}

